use alloc::borrow::Cow;
use alloc::string::String;

use crate::TypeDef;

/// A static description of one column in a table.
///
/// Generated by `#[derive(Table)]` into the table's [`TableDef`], and consumed by schema
/// generation, migration diffing and introspection.
#[derive(Debug, Clone, PartialEq)]
pub struct ColumnDef {
    /// The column name exactly as it appears in SQL.
    pub name: &'static str,
    /// The canonical type of the column.
    pub ty: TypeDef,
    /// Whether the column accepts `NULL`.
    pub nullable: bool,
    /// Whether the database generates the value (`SERIAL`, `AUTO_INCREMENT`, ...).
    ///
    /// A generated column sets this too, because its value is equally not supplied by the
    /// program; [`ColumnDef::generated`] distinguishes the two spellings.
    pub auto_increment: bool,
    /// Whether the column is part of the primary key.
    pub primary_key: bool,
    /// Whether the column has a `UNIQUE` constraint of its own.
    pub unique: bool,
    /// A literal default value, rendered by each dialect.
    pub default: Option<DefaultValue>,
    /// How the database computes this column, if it is generated.
    ///
    /// A generated column is never written by an `INSERT` or an `UPDATE`: the value is a
    /// function of the other columns, so the derive leaves it out of the insert struct and
    /// whole-row updates skip it. Declaring it in the static metadata is what lets DDL and
    /// introspection agree about the column, instead of treating it as an ordinary one.
    pub generated: Option<Generated>,
    /// The column's previous name, if it was renamed.
    ///
    /// A pure diff cannot tell a rename from a drop plus an add, and guessing would be
    /// dangerous, so the intent is declared instead. Migrations then emit
    /// `ALTER TABLE ... RENAME COLUMN` and the data survives.
    pub renamed_from: Option<&'static str>,
}

/// A column whose value the database computes from other columns.
///
/// The expression is raw SQL, written verbatim inside `GENERATED ALWAYS AS (...)`. It cannot
/// be checked by Besu, and the same expression is not portable across dialects, so it is the
/// caller's responsibility that all three accept it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Generated {
    /// The SQL expression that computes the value.
    pub expression: &'static str,
    /// Whether the value is stored on disk (`STORED`) or computed on read (`VIRTUAL`).
    ///
    /// PostgreSQL only implements stored generated columns, so a virtual column is created
    /// there as a stored one.
    pub stored: bool,
}

/// A column default, kept in a form each dialect can render.
#[derive(Debug, Clone, Copy, PartialEq)]
#[non_exhaustive]
pub enum DefaultValue {
    /// `DEFAULT NULL` (or, equivalently, no default).
    Null,
    /// A boolean literal.
    Bool(bool),
    /// An integer literal.
    Int(i64),
    /// A float literal.
    Float(f64),
    /// A string literal.
    Text(&'static str),
    /// A raw SQL expression, inserted verbatim. This is the escape hatch and is unchecked.
    Raw(&'static str),
    /// `CURRENT_TIMESTAMP`.
    Now,
}

impl DefaultValue {
    /// Render the literal part of the default. Raw values pass through untouched.
    pub fn render(&self) -> Cow<'static, str> {
        match self {
            Self::Null => Cow::Borrowed("NULL"),
            Self::Bool(true) => Cow::Borrowed("TRUE"),
            Self::Bool(false) => Cow::Borrowed("FALSE"),
            Self::Int(v) => Cow::Owned(alloc::format!("{v}")),
            Self::Float(v) => Cow::Owned(alloc::format!("{v}")),
            Self::Text(v) => Cow::Owned(alloc::format!("'{}'", v.replace('\'', "''"))),
            Self::Raw(v) => Cow::Borrowed(v),
            Self::Now => Cow::Borrowed("CURRENT_TIMESTAMP"),
        }
    }
}

/// The access method an index is built with.
///
/// A b-tree is the default everywhere and the only kind SQLite has. PostgreSQL names its
/// methods in `pg_am`; MySQL spells two of them in the index syntax itself. The enum is
/// deliberately small: these are the methods that change what a query planner can do, and
/// the dialect that implements one reports it back through introspection.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, serde::Serialize, serde::Deserialize)]
#[non_exhaustive]
pub enum IndexKind {
    /// The default ordered index, `btree` on PostgreSQL and `BTREE` on MySQL.
    #[default]
    Btree,
    /// A MySQL `FULLTEXT` index, which `MATCH ... AGAINST` requires.
    FullText,
    /// A MySQL `SPATIAL` index over a geometry column.
    Spatial,
    /// A PostgreSQL GIN index, for `jsonb`, arrays, `tsvector` and trigram search.
    Gin,
    /// A PostgreSQL GiST index, for ranges, geometry and nearest-neighbour search.
    Gist,
    /// A PostgreSQL BRIN index, for large append-only tables.
    Brin,
}

impl IndexKind {
    /// The spelling the catalogue uses, which is also the PostgreSQL `USING` clause.
    ///
    /// `fulltext` and `spatial` are MySQL's spellings, not PostgreSQL access methods; the
    /// PostgreSQL dialect maps them onto `gin` and `gist` when it renders DDL.
    pub const fn as_str(&self) -> &'static str {
        match self {
            Self::Btree => "btree",
            Self::FullText => "fulltext",
            Self::Spatial => "spatial",
            Self::Gin => "gin",
            Self::Gist => "gist",
            Self::Brin => "brin",
        }
    }

    /// Whether this is the default access method, which snapshots leave out.
    pub const fn is_btree(&self) -> bool {
        matches!(self, Self::Btree)
    }
}

/// A secondary index declaration.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Index {
    /// The index name.
    pub name: &'static str,
    /// The columns the index covers, in order.
    pub columns: &'static [&'static str],
    /// Whether the index enforces uniqueness.
    pub unique: bool,
    /// The access method the index uses.
    pub kind: IndexKind,
}

/// A foreign key constraint.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ForeignKey {
    /// The constraint name.
    pub name: &'static str,
    /// Columns on this table.
    pub columns: &'static [&'static str],
    /// The table being referenced.
    pub references_table: &'static str,
    /// Columns on the referenced table.
    pub references_columns: &'static [&'static str],
    /// What to do when the referenced row is deleted.
    pub on_delete: ReferenceAction,
    /// What to do when the referenced row is updated.
    pub on_update: ReferenceAction,
}

/// The action taken by a foreign key when the referenced row changes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, serde::Serialize, serde::Deserialize)]
#[non_exhaustive]
pub enum ReferenceAction {
    /// Let the database decide (usually `NO ACTION`).
    #[default]
    Default,
    /// `CASCADE`
    Cascade,
    /// `SET NULL`
    SetNull,
    /// `SET DEFAULT`
    SetDefault,
    /// `RESTRICT`
    Restrict,
    /// `NO ACTION`
    NoAction,
}

impl ReferenceAction {
    /// Render the action for a DDL statement.
    pub const fn as_sql(&self) -> Option<&'static str> {
        match self {
            Self::Default => None,
            Self::Cascade => Some("CASCADE"),
            Self::SetNull => Some("SET NULL"),
            Self::SetDefault => Some("SET DEFAULT"),
            Self::Restrict => Some("RESTRICT"),
            Self::NoAction => Some("NO ACTION"),
        }
    }
}

/// The static description of a table, produced by `#[derive(Table)]`.
///
/// This is the metadata the whole system is built on: query builders read the column list
/// from it, migrations diff it against a live database, and the CLI turns it back into
/// Rust code.
#[derive(Debug, Clone, PartialEq)]
pub struct TableDef {
    /// The table name exactly as it appears in SQL.
    pub name: &'static str,
    /// An optional schema or database namespace.
    ///
    /// Every dialect qualifies the name when this is set; PostgreSQL calls it a schema and
    /// MySQL calls it a database. SQLite attached databases work the same way, but SQLite
    /// itself ignores the distinction for a normal file.
    pub schema: Option<&'static str>,
    /// Every column, in the order the model's fields are declared. This ordering is
    /// load-bearing: `SELECT` lists and row decoding both follow it.
    pub columns: &'static [ColumnDef],
    /// Secondary indexes.
    pub indexes: &'static [Index],
    /// Foreign keys.
    pub foreign_keys: &'static [ForeignKey],
    /// Whether `push` should enable row-level security on this table.
    ///
    /// Only PostgreSQL implements it. Enabling is safe and happens on creation or as an
    /// `ALTER TABLE ... ENABLE ROW LEVEL SECURITY`; it is deliberately never disabled
    /// automatically, because disabling one removes a guarantee every policy depends on.
    pub rls: bool,
}

impl TableDef {
    /// The primary key columns, in declaration order.
    pub fn primary_key(&self) -> impl Iterator<Item = &ColumnDef> {
        self.columns.iter().filter(|c| c.primary_key)
    }

    /// Whether the table has a composite primary key.
    pub fn has_composite_primary_key(&self) -> bool {
        self.columns.iter().filter(|c| c.primary_key).count() > 1
    }

    /// Look up a column by SQL name.
    pub fn column(&self, name: &str) -> Option<&ColumnDef> {
        self.columns.iter().find(|c| c.name == name)
    }

    /// The `SELECT` list for the whole table, unqualified and comma separated.
    pub fn projection(&self) -> String {
        let mut out = String::new();
        for (i, column) in self.columns.iter().enumerate() {
            if i != 0 {
                out.push_str(", ");
            }
            out.push_str(column.name);
        }
        out
    }
}
